/* ORION 2.0. Static public evidence, browser-local decisions, no booking actions. */
(() => {
'use strict';
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name, cls='') => `<svg class="icon ${cls}" aria-hidden="true"><use href="assets/icons.svg#${name}"></use></svg>`;
const base = new URL('.', document.baseURI);
const STORAGE='orion.v2.';
const store={read(key,fallback){try{const v=JSON.parse(localStorage.getItem(STORAGE+key));return v??fallback}catch{return fallback}},write(key,v){try{localStorage.setItem(STORAGE+key,JSON.stringify(v));return true}catch{return false}}};
const fmtGBP=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0});
const fmtExact=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',minimumFractionDigits:2,maximumFractionDigits:2});
const fmtNum=new Intl.NumberFormat('en-GB');
const money=(n,exact=false)=>Number.isFinite(n)?(exact?fmtExact:fmtGBP).format(n/100):'Not published';
const day=x=>{const t=typeof x==='number'?x:Date.parse(String(x).length===10?x+'T12:00:00Z':x);return Number.isFinite(t)?new Date(t).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/London'}):'Not recorded'};
const shortDay=x=>new Date(x).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Europe/London'});
const dateTime=x=>{const t=typeof x==='number'?x:Date.parse(x);return Number.isFinite(t)?new Date(t).toLocaleString('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Europe/London',timeZoneName:'short'}):'Not recorded'};
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const norm=s=>String(s??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const pct=n=>Number.isFinite(n)?(n>0&&n<.05?'<0.1':n.toFixed(1))+'%':'No change recorded';
const safeURL=s=>{try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null}catch{return null}};
const withLink=(s,label)=>{const u=safeURL(s);return u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('arrow-up-right','sm')}</a>`:''};
const info=(key,label)=>`<button class="info-btn" data-action="tip" data-tip="${esc(key)}" aria-label="${esc(label)}">i</button>`;
const validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')&&Number.isFinite(Date.parse(v));
const strTime=t=>new Date(t).toISOString().slice(0,10);
const MODAL_TRIGGER=new WeakMap();
const MODAL_STACK=[];
let theme=store.read('appearance','system');
if(!['light','dark','system'].includes(theme))theme='system';
function applyTheme(){if(theme==='system')document.documentElement.removeAttribute('data-theme');else document.documentElement.dataset.theme=theme;const b=$('themeButton');if(b)b.setAttribute('aria-label','Appearance: '+theme+'. Activate to switch.');}
applyTheme();
const palette=()=>{const c=getComputedStyle(document.documentElement);return {blue:c.getPropertyValue('--blue').trim(),ink:c.getPropertyValue('--ink').trim(),muted:c.getPropertyValue('--muted').trim(),line:c.getPropertyValue('--line').trim(),bg:c.getPropertyValue('--surface').trim()}};
let toastTimer;
function toast(text){const e=$('toast');if(!e)return;clearTimeout(toastTimer);e.textContent=text;e.hidden=false;toastTimer=setTimeout(()=>{e.hidden=true},4200)}
function modalOpen(id){const d=$(id);if(!d)return;if(!d.open){MODAL_TRIGGER.set(d,document.activeElement);d.showModal();MODAL_STACK.push(d);}}
function modalClose(id){const d=$(id);if(d?.open)d.close()}
for(const d of document.querySelectorAll('dialog')){
 d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
 d.addEventListener('close',()=>{const i=MODAL_STACK.indexOf(d);if(i>=0)MODAL_STACK.splice(i,1);const p=$('tipPopover');if(p&&d.contains(p)){if(p.matches(':popover-open'))p.hidePopover();document.body.appendChild(p)}const target=MODAL_TRIGGER.get(d);if(target?.isConnected)target.focus({preventScroll:true});if(d.id==='voyageDialog'){DETAIL_ID=null;destroyDetailChart();writeURL()}});
}
async function copyText(text,success){try{await navigator.clipboard.writeText(text);toast(success);return true}catch{
 const t=document.createElement('textarea');t.value=text;t.setAttribute('aria-label','Text to copy');Object.assign(t.style,{position:'fixed',left:'-9999px',top:'0'});document.body.appendChild(t);t.select();let ok=false;try{ok=document.execCommand('copy')}catch{}t.remove();if(ok){toast(success);return true}
 const d=$('statusDialog');if(d){$('statusTitle').textContent='Copy this text';$('statusContent').innerHTML=`<p class="section-caption">Your browser blocked automatic copying. Select and copy the text below.</p><textarea class="quote-preview" aria-label="Text to copy" style="width:100%;height:240px">${esc(text)}</textarea>`;modalOpen('statusDialog');$('statusContent').querySelector('textarea').select()}else toast('Copying is unavailable in this browser.');return false;
}}
let HELP=null,HELP_ID='start';
const helpPromise=fetch(new URL('assets/help.json',base)).then(r=>{if(!r.ok)throw Error('Help HTTP '+r.status);return r.json()}).then(d=>{if(!Array.isArray(d.articles))throw Error('Invalid help content');HELP=d;return d}).catch(e=>{console.warn('ORION help:',e.message);return null});
function renderHelp(query='',requested){if(!HELP){$('helpArticle').innerHTML='<p>The searchable guide could not load. Read the <a href="GUIDE.md">complete text guide</a>.</p>';return}
 const q=norm(query).trim();const docs=HELP.articles.filter(a=>!q||norm(a.title+' '+a.intro+' '+a.blocks.map(b=>b.heading+' '+b.text).join(' ')).includes(q));
 if(requested)HELP_ID=requested;
 if(!docs.some(a=>a.id===HELP_ID))HELP_ID=docs[0]?.id;
 const nav=$('helpNav');nav.replaceChildren();let group='';
 for(const a of docs){if(group!==a.section){const p=document.createElement('div');p.className='help-group-label';p.textContent=a.section;nav.appendChild(p);group=a.section}const b=document.createElement('button');b.className='help-topic';b.dataset.helpTopic=a.id;b.textContent=a.title;if(a.id===HELP_ID)b.setAttribute('aria-current','page');nav.appendChild(b)}
 const a=docs.find(x=>x.id===HELP_ID);if(!a){$('helpArticle').innerHTML='<div class="empty-state"><h3>No matching guide topic</h3><p>Try “prices”, “dates”, “saved” or “updates”.</p></div>';return}
 $('helpArticle').innerHTML=`<div class="eyebrow">${esc(a.section)}</div><h3>${esc(a.title)}</h3><p class="article-intro">${esc(a.intro)}</p>${a.blocks.map(b=>`<section><h4>${esc(b.heading)}</h4><p>${esc(b.text)}</p></section>`).join('')}<div class="article-footer"><span>Guide for ORION 2.0 · No booking actions</span><a href="help.html?topic=${encodeURIComponent(a.id)}" target="_blank" rel="noopener noreferrer">Open this topic separately ${icon('arrow-up-right','sm')}</a></div>`;
}
async function openHelp(topic='start'){await helpPromise;if($('tipPopover')?.matches(':popover-open'))$('tipPopover').hidePopover();if($('helpSearch'))$('helpSearch').value='';renderHelp('',topic);if(document.body.dataset.mode!=='help')modalOpen('helpDialog');else history.replaceState(null,'','?topic='+encodeURIComponent(topic));}
let tipTrigger=null;
async function openTip(key,trigger){await helpPromise;const x=HELP?.tips[key];if(!x)return;const p=$('tipPopover');if(!p){openHelp(x.topic);return}const host=trigger.closest('dialog')||document.body;if(p.parentElement!==host){if(p.matches(':popover-open'))p.hidePopover();host.appendChild(p)}tipTrigger?.setAttribute('aria-expanded','false');tipTrigger=trigger;trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-controls','tipPopover');$('tipTitle').textContent=x.title;$('tipText').textContent=x.text;$('tipMore').dataset.topic=x.topic;if(!p.matches(':popover-open'))p.showPopover();const rect=trigger.getBoundingClientRect();requestAnimationFrame(()=>{const box=p.getBoundingClientRect();const left=Math.max(12,Math.min(window.innerWidth-box.width-12,rect.left-15));let top=rect.bottom+9;if(top+box.height>window.innerHeight-12)top=Math.max(12,rect.top-box.height-9);p.style.left=left+'px';p.style.top=top+'px';})}
$('tipPopover')?.addEventListener('toggle',e=>{if(e.newState==='closed')tipTrigger?.setAttribute('aria-expanded','false')});
$('tipMore')?.addEventListener('click',()=>openHelp($('tipMore').dataset.topic));
$('helpSearch')?.addEventListener('input',e=>renderHelp(e.target.value));
document.addEventListener('click',e=>{const t=e.target.closest('[data-help-topic]');if(t){renderHelp($('helpSearch').value,t.dataset.helpTopic);$('helpArticle').focus({preventScroll:true});if(document.body.dataset.mode==='help')history.replaceState(null,'','?topic='+encodeURIComponent(t.dataset.helpTopic))}const c=e.target.closest('[data-close]');if(c)modalClose(c.dataset.close)});
if(document.body.dataset.mode==='help'){
 document.addEventListener('click',e=>{if(e.target.closest('[data-action="theme"]')){theme=theme==='system'?'light':theme==='light'?'dark':'system';store.write('appearance',theme);applyTheme();toast('Appearance: '+theme)}});
 helpPromise.then(()=>renderHelp('',new URLSearchParams(location.search).get('topic')||'start'));return;
}

const DEFAULT={q:'',region:'',ship:'',from:'',to:'',budget:'',duration:'',kind:'',cabin:'',view:'all',evidence:'all',sort:'date',page:1};
let state={...DEFAULT},DATA=null,PRODUCTS=[],BY_ID=new Map(),PAGE_SIZE=12;
let saved=new Set(Array.isArray(store.read('saved',[]))?store.read('saved',[]):[]);
let compared=new Set(Array.isArray(store.read('compare',[]))?store.read('compare',[]).slice(0,3):[]);
let layout=store.read('layout','cards');if(!['cards','list'].includes(layout))layout='cards';
let DETAIL_ID=null,DETAIL_TAB='overview',DETAIL=null,DETAIL_COLUMN='',DETAIL_SEQUENCE=0,DETAIL_RENDER=0;
const detailFiles=new Map();let detailChart=null,calendarChart=null,CALENDAR_OPEN=false;
let helpInit=false,initialLoad=true;
function snapshotAge(){const t=Date.parse(DATA?.feed?.observed_at);return Number.isFinite(t)?Math.max(0,(Date.now()-t)/3600000):Infinity}
function readURL(){const p=new URLSearchParams(location.search),s={...DEFAULT};for(const k of Object.keys(DEFAULT)){if(p.has(k))s[k]=p.get(k)}
 if(!['all','drops','saved','offers'].includes(s.view)){if(s.view==='agency'){s.evidence='agency';s.view='all'}else if(s.view==='verified'){s.evidence='verified';s.view='all'}else s.view='all'}
 if(!['all','agency','verified'].includes(s.evidence))s.evidence='all';if(!['date','price','drop','daily','latest'].includes(s.sort))s.sort='date';
 for(const k of ['from','to'])if(s[k]&&!validDate(s[k]))s[k]='';
 if(s.from&&s.to&&s.from>s.to){s.from='';s.to=''}
 if(s.budget&&(!Number.isFinite(Number(s.budget))||Number(s.budget)<=0))s.budget='';
 if(!['','short','medium','long'].includes(s.duration))s.duration='';
 s.page=Math.max(1,Math.min(999,parseInt(s.page,10)||1));state=s;return p;
}
function writeURL(){if(!DATA)return;const p=new URLSearchParams();for(const [k,v] of Object.entries(state)){if(v!==DEFAULT[k]&&v!==''&&!(k==='page'&&v===1))p.set(k,String(v))}if(DETAIL_ID){p.set('voyage',DETAIL_ID);if(DETAIL_TAB!=='overview')p.set('tab',DETAIL_TAB)}history.replaceState(null,'',location.pathname+(p.size?'?'+p.toString():''));}
function populateSelect(id,items,label){const e=$(id);if(!e)return;const keep=e.value;e.replaceChildren();const d=document.createElement('option');d.value='';d.textContent=label;e.appendChild(d);[...new Set(items.filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b))).forEach(v=>{const op=document.createElement('option');op.value=v;op.textContent=v;e.appendChild(op)});e.value=keep;}
function syncFields(){$('query').value=state.q;$('region').value=state.region;$('sort').value=state.sort;}
function fare(r){const a=r.fares||[];if(state.cabin){const f=a.find(f=>f[0]===state.cabin);return f?{column:f[0],amount:f[1]}:null}const f=a.reduce((x,y)=>!x||y[1]<x[1]?y:x,null);return f?{column:f[0],amount:f[1]}:null}
function drop(r){if(state.cabin){const x=r.changes?.[state.cabin];return x&&x[0]>0?{column:state.cabin,pct:x[0],current:x[1],previous:x[2]}:null}return r.drop?.pct>0?r.drop:null}
function matches(r){if(state.view==='saved'&&!saved.has(r.id))return false;if(state.q&&!norm(state.q).trim().split(/\s+/).every(t=>r._search.includes(t)))return false;
 for(const k of ['region','ship','kind'])if(state[k]&&r[k]!==state[k])return false;
 if(state.from&&r.departure<state.from||state.to&&r.departure>state.to)return false;
 const d=Number(r.duration);if(state.duration==='short'&&d>7||state.duration==='medium'&&(d<8||d>14)||state.duration==='long'&&d<15)return false;
 const f=fare(r);if(!f&&(state.cabin||state.budget))return false;if(state.budget&&f.amount*2>Number(state.budget)*100)return false;
 if(state.view==='drops'&&!drop(r))return false;if(state.evidence==='agency'&&!r.retail_advert_count)return false;if(state.evidence==='verified')return false;return true;
}
function filtered(){const a=PRODUCTS.filter(matches);a.sort((x,y)=>{const xp=fare(x)?.amount??Infinity,yp=fare(y)?.amount??Infinity;if(state.sort==='price')return xp-yp||x.departure.localeCompare(y.departure);if(state.sort==='daily')return xp/x.duration-yp/y.duration;if(state.sort==='latest')return y.departure.localeCompare(x.departure);if(state.sort==='drop')return (drop(y)?.pct||0)-(drop(x)?.pct||0)||x.departure.localeCompare(y.departure);return x.departure.localeCompare(y.departure)||xp-yp});return a}
function noticeTitle(){if(state.view==='saved')return ['Keep the good ones.','Your shortlist, saved on this browser. No bookings or alerts.','Saved voyages'];if(state.view==='drops')return ['Follow the price trail.','Recorded supplier changes, with the evidence behind them.','Recorded price drops'];if(state.view==='offers')return ['Know what really applies.','Understand eligibility and combinations before chasing a benefit.','Offers'];return ['A better view<br>of your next voyage.','Discover Windstar departures, compare the evidence<br class="desktop-break"> and keep the ones worth a closer look.','Explore departures']}
function renderChips(){const chips=[];for(const k of ['q','region','ship','from','to','budget','duration','kind','cabin']){const v=state[k];if(!v)continue;const labels={q:'Search: '+v,region:v,ship:v,from:'From '+day(v),to:'Until '+day(v),budget:'Guide up to '+fmtGBP.format(Number(v)),duration:({'short':'1–7 days','medium':'8–14 days','long':'15+ days'})[v],kind:v,cabin:'Column '+v};chips.push(`<button class="chip" data-remove-filter="${k}" aria-label="Remove ${esc(labels[k])}">${esc(labels[k])}${icon('x')}</button>`)}if(chips.length)chips.push('<button class="chip-clear" data-action="reset">Clear all</button>');$('chips').innerHTML=chips.join('');const n=Object.keys(state).filter(k=>['ship','from','to','budget','duration','kind','cabin'].includes(k)&&state[k]).length;$('filterCount').textContent=n;$('filterCount').hidden=!n;$('whenLabel').textContent=state.from||state.to?'Dates set':'Any dates';}
function renderHeader(){const [title,caption,section]=noticeTitle();$('pageTitle').innerHTML=title;$('pageIntro').innerHTML=caption;$('exploreTitle').textContent=section;$('sectionSub').textContent=state.view==='drops'?'Same published fare column. Not a verified retail saving.':state.view==='saved'?'Your saved departures. Filter, compare or export them.':'Worldwide. Your dates. A clearer comparison.';document.querySelectorAll('[data-view]').forEach(b=>{if(b.closest('.main-nav')){if(b.dataset.view===state.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}});$('savedCount').textContent=saved.size;$('savedNotice').hidden=state.view!=='saved';$('exportButton').hidden=state.view!=='saved';$('exportButton').disabled=!saved.size;$('exploreSection').hidden=state.view==='offers';$('offersSection').hidden=state.view!=='offers';document.querySelectorAll('[data-quick]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.quick===state.evidence)));document.querySelectorAll('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layout===layout)));}
function saveButton(r,large=false){const on=saved.has(r.id);return `<button class="${large?'button secondary':'icon-btn save-button'}${on?' selected':''}" data-action="save" data-id="${esc(r.id)}" aria-pressed="${on}" aria-label="${on?'Unsave':'Save'} ${esc(r.itinerary)}">${icon(on?'bookmark-check':'bookmark')}${large?`<span class="label-hide">${on?'Saved':'Save'}</span>`:''}</button>`}
function compareControl(r){const on=compared.has(r.id);return `<button class="compare-select" data-action="select-compare" data-id="${esc(r.id)}" aria-pressed="${on}" aria-label="${on?'Remove from':'Add to'} comparison: ${esc(r.itinerary)}"><span class="box">${on?icon('check'):''}</span>Compare</button>`}
function card(r){const f=fare(r),d=drop(r);const dates=DATA.families?.[r.family_id]||1;return `<article class="voyage-card"><div class="card-main"><div class="card-top"><span class="ship-label">${icon('ship')}${esc(r.ship)}</span>${saveButton(r)}</div><p class="card-region">${esc(r.region)}</p><h3 class="card-title">${esc(r.itinerary)}</h3><p class="card-route">${esc(r.from_port)} → ${esc(r.to_port)}</p><div class="card-date">${icon('calendar-days')}${esc(day(r.departure))}<span class="date-sep">·</span>${esc(r.duration)} published days</div><div class="product-kind">${r.kind==='Cruise'?'Cruise':esc(r.kind)}</div><div class="card-price-row"><div><div class="price-caption">Estimated cruise guide ${info('guide','About this price guide')}</div><div class="price-figure">${money(f?.amount*2)}<small>for 2</small></div></div>${d?`<button class="evidence-badge" data-action="voyage" data-id="${esc(r.id)}" data-tab="history" data-column="${esc(d.column)}" aria-label="See the ${esc(pct(d.pct))} recorded drop in ${esc(d.column)}">${icon('trending-down')}Up to ${pct(d.pct)} drop</button>`:`<span class="evidence-badge neutral">Published guide</span>`}</div><div class="card-evidence"><span>${r.retail_advert_count?`${icon('columns-3')}${r.retail_advert_count} seller price records`:'Seller quote still needed'}</span><button class="text-link" data-action="voyage" data-id="${esc(r.id)}" data-tab="dates">${dates>1?dates+' dates':'View dates'} ${icon('arrow-right','sm')}</button></div></div><div class="card-actions"><button class="button secondary" data-action="voyage" data-id="${esc(r.id)}">View voyage ${icon('arrow-right','sm')}</button>${compareControl(r)}</div></article>`}
function listRows(rows){return `<div class="list-wrap"><table class="data-table"><caption class="sr-only">Matching voyage guides and evidence</caption><thead><tr><th scope="col">Voyage</th><th scope="col">Departure</th><th scope="col">Guide for 2</th><th scope="col">Evidence</th><th scope="col">Shortlist</th></tr></thead><tbody>${rows.map(r=>{const d=drop(r);return `<tr><td><button class="list-title" data-action="voyage" data-id="${esc(r.id)}">${esc(r.itinerary)}</button><small>${esc(r.ship)} · ${esc(r.region)}</small></td><td>${esc(day(r.departure))}<small>${r.duration} published days</small></td><td class="money"><strong>${money(fare(r)?.amount*2)}</strong><small>Unverified estimate</small></td><td>${d?`<button class="evidence-badge" data-action="voyage" data-id="${esc(r.id)}" data-tab="history" data-column="${esc(d.column)}">${icon('trending-down')}Up to ${pct(d.pct)} drop</button>`:'No recorded decrease'}<small>${r.retail_advert_count||0} seller records</small></td><td><div class="row-actions">${saveButton(r)}${compareControl(r)}</div></td></tr>`}).join('')}</tbody></table></div>`}
function emptyMarkup(){if(state.evidence==='verified')return `<div class="empty-state">${icon('shield-check')}<h3>No verified exceptional bargains yet.</h3><p>Published price drops are useful leads. A confirmed saving needs the same cabin, full UK costs and real availability, checked against an independent seller.</p><button class="button secondary" data-action="unverify">Explore the published guides ${icon('arrow-right')}</button> <button class="button quiet" data-action="help" data-topic="verification">Read the verification standard</button></div>`;if(state.view==='saved'&&!saved.size)return `<div class="empty-state">${icon('bookmark')}<h3>Keep something worth coming back to.</h3><p>Bookmark a voyage while exploring and it will appear here. Your shortlist stays on this browser; it does not create an alert or booking.</p><button class="button primary" data-view="all">Explore voyages ${icon('arrow-right')}</button></div>`;return `<div class="empty-state">${icon('sliders-horizontal')}<h3>A little more room to explore?</h3><p>No published departures match this combination. Try a wider date range, another region or a higher cruise-guide budget.</p><button class="button secondary" data-action="reset">Clear these filters</button></div>`}
function renderPagination(total){const pages=Math.ceil(total/PAGE_SIZE),e=$('pagination');e.hidden=pages<=1;if(pages<=1)return;let nums=[1,pages,state.page-1,state.page,state.page+1].filter(n=>n>=1&&n<=pages);nums=[...new Set(nums)].sort((a,b)=>a-b);let last=0,buttons='';for(const n of nums){if(n>last+1)buttons+='<span aria-hidden="true">…</span>';buttons+=`<button class="page-button" data-page="${n}" ${n===state.page?'aria-current="page"':''} aria-label="Page ${n}">${n}</button>`;last=n}e.innerHTML=`<span>${fmtNum.format((state.page-1)*PAGE_SIZE+1)}–${fmtNum.format(Math.min(total,state.page*PAGE_SIZE))} of ${fmtNum.format(total)} departures</span><div class="page-controls"><button class="page-button" data-page="${state.page-1}" ${state.page===1?'disabled':''} aria-label="Previous page">${icon('chevron-left')}</button>${buttons}<button class="page-button" data-page="${state.page+1}" ${state.page===pages?'disabled':''} aria-label="Next page">${icon('chevron-right')}</button></div>`}
function updateCompareTray(){const n=compared.size;$('compareTray').hidden=!n;$('compareCount').textContent=n+' voyage'+(n===1?'':'s')+' selected';$('compareButtonCount').textContent=n;$('compareNames').textContent=[...compared].map(id=>BY_ID.get(id)?.itinerary).filter(Boolean).join(' · ');}
function render({scroll=false}={}){if(!DATA)return;renderHeader();syncFields();renderChips();updateCompareTray();writeURL();if(state.view==='offers'){renderOffers();return}const a=filtered();state.page=Math.min(state.page,Math.max(1,Math.ceil(a.length/PAGE_SIZE)));const page=a.slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE);$('resultCount').textContent=fmtNum.format(a.length)+' departure'+(a.length===1?'':'s');$('resultNote').textContent=state.view==='drops'?'Recorded raw changes. Not confirmed discounts.':'Guides for two adults, in GBP.';$('results').className=layout==='cards'?'voyage-grid':'voyage-grid list-mode';$('results').innerHTML=a.length?(layout==='cards'?page.map(card).join(''):listRows(page)):emptyMarkup();renderPagination(a.length);if(CALENDAR_OPEN)renderCalendar(a);writeURL();if(scroll)$('resultCount').scrollIntoView({behavior:'auto',block:'start'});}
function resetFilters(){const view=state.view==='offers'?'all':state.view;state={...DEFAULT,view,sort:view==='drops'?'drop':'date'};render();}
function nav(view){state.view=view;state.evidence='all';state.page=1;state.sort=view==='drops'?'drop':'date';if(view==='saved'){state={...DEFAULT,view:'saved'}}render();}
function toggleSaved(id){if(!BY_ID.has(id))return;if(saved.has(id)){saved.delete(id);toast('Removed from your saved voyages.')}else{saved.add(id);toast('Saved on this browser. No alert or booking created.')}if(!store.write('saved',[...saved]))toast('Saved for this visit only. Browser storage is unavailable.');render();if($('voyageDialog').open)updateVoyageFooter();}
function toggleCompare(id){if(compared.has(id))compared.delete(id);else if(compared.size<3)compared.add(id);else{toast('Compare up to three voyages. Remove one before adding another.');return}store.write('compare',[...compared]);render();if($('voyageDialog').open)updateVoyageFooter();}
function showFilters(focus){for(const k of ['from','to','ship','duration','budget','kind','cabin']){const e=$('filter'+k[0].toUpperCase()+k.slice(1));if(e)e.value=state[k]}$('filterTo').setCustomValidity('');modalOpen('filterDialog');if(focus)requestAnimationFrame(()=>$(focus)?.focus());}
function makeQuote(r,column){return `Please send a written quote for two UK-resident adults sharing on this Windstar voyage:\n\n${r.ship}\n${r.itinerary}\nDeparture: ${day(r.departure)}\nSupplier cruise ID: ${r.cruise_id}\nPublished duration: ${r.duration} days. Please confirm the actual cruise nights.\n${column?'Supplier price column of interest: '+column+'. Please confirm the exact cabin grade.':'Please specify the exact cabin grade and the lowest suitable available cabin.'}\n\nPlease confirm the final GBP total for two, including all mandatory taxes, port charges, gratuities and agency fees. Itemise any flights, hotels or transfers separately. Confirm whether All-Inclusive, loyalty or agency benefits are included and which can combine.\n\nPlease also confirm UK residency eligibility, live cabin availability, deposit, cancellation terms, quote expiry and any booking protection.\n\nI saw this as an unverified public price guide, not a final booking quote. No booking or hold is authorised by this request.`;}

async function fetchJSON(path){const u=new URL(path,base);if(u.origin!==base.origin||!u.pathname.startsWith(base.pathname))throw Error('Unexpected data location');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(u,{signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(timer)}}
async function detailFor(r){const path=DATA.detail_files?.[r.ship];if(!path)throw Error('No detailed evidence file is published for this ship.');if(!detailFiles.has(path)){detailFiles.set(path,fetchJSON(path).then(d=>{if(d.schema_version!==2||!d.products)throw Error('Invalid detail file');return d.products}).catch(e=>{detailFiles.delete(path);throw e}))}const records=await detailFiles.get(path),record=records[r.id];if(!record)throw Error('This product is absent from the detailed snapshot.');return {...r,...record}}
function destroyDetailChart(){if(detailChart){detailChart.destroy();detailChart=null}}
async function openVoyage(id,tab='overview',column=''){const r=BY_ID.get(id);if(!r){toast('That departure is not present in this published catalogue.');return}DETAIL_ID=id;DETAIL_TAB=['overview','prices','dates','history'].includes(tab)?tab:'overview';DETAIL_COLUMN=column||state.cabin||drop(r)?.column||r.fares[0]?.[0]||'';DETAIL=null;const seq=++DETAIL_SEQUENCE;writeURL();$('voyageContent').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">${esc(r.ship)}</span><h2 id="voyageTitle">${esc(r.itinerary)}</h2></div><button class="icon-btn close" data-close="voyageDialog" aria-label="Close voyage">${icon('x')}</button></div><div class="dialog-content"><div class="loading-state" role="status"><span class="spinner"></span><h3>Opening the evidence</h3><p>Loading only this ship's detailed prices and saved observations.</p></div></div>`;modalOpen('voyageDialog');try{const d=await detailFor(r);if(seq!==DETAIL_SEQUENCE||DETAIL_ID!==id||!$('voyageDialog').open)return;DETAIL=d;renderVoyage()}catch(e){if(seq!==DETAIL_SEQUENCE)return;$('voyageContent').innerHTML=`<div class="dialog-head"><h2 id="voyageTitle">${esc(r.itinerary)}</h2><button class="icon-btn close" data-close="voyageDialog" aria-label="Close voyage">${icon('x')}</button></div><div class="dialog-content"><div class="empty-state">${icon('cloud-off')}<h3>Details couldn't be loaded.</h3><p>The summary remains available. No missing evidence is being treated as confirmed.</p><button class="button secondary" data-action="retry-detail">Try again</button></div></div>`;console.warn('ORION detail:',e.message)}}
function detailRate(){if(!DETAIL)return null;return fare(DETAIL)||{column:DETAIL.fares[0]?.[0],amount:DETAIL.fares[0]?.[1]}}
function overviewHTML(r){const f=detailRate(),d=drop(r);const points=Object.values(r.price_history||{}).map(x=>x.observations||0);const maxPoints=points.length?Math.max(...points):0;
 return `<div class="detail-summary"><div><div class="detail-label">Estimated cruise guide for two ${info('guide','About the estimated guide')}</div><div class="detail-price">${money(f?.amount*2,true)}<small>GBP</small></div><p class="detail-meta">From supplier column <strong>${esc(f?.column||'unknown')}</strong>. Not a final quotation.<br>Feed observed ${esc(dateTime(DATA.feed.observed_at))}.</p></div><div class="summary-evidence"><h3>${d?'A price change worth checking.':'A starting point for a quote.'}</h3><p>${d?`Column <strong>${esc(d.column)}</strong> fell ${esc(pct(d.pct))} between saved checks. It may differ from the cheapest column shown here. Confirm today's equivalent retail price.`:'The supplier publishes this price, but a current available cabin and full UK payable total have not been confirmed.'}</p>${d?`<button class="text-link" data-action="detail-tab" data-tab="history" data-column="${esc(d.column)}">Inspect the change ${icon('arrow-right','sm')}</button>`:''}</div></div><div class="notice">${r.retail_prices?.length?`<strong>${r.retail_prices.length} retained seller price records</strong> are matched to this exact product. They still need cabin, inclusion and current-price checks.`:'No matched seller-price evidence is stored for this exact product yet.'} ${maxPoints?`There are up to ${maxPoints} saved observations per supplier column.`:''}</div><h3 class="detail-heading">Confirm before you book</h3><p class="section-caption">The important questions stay visible, even when the headline looks tempting.</p><div class="quote-checks">${['Available cabin','Exact cabin grade','UK eligibility','Mandatory charges','All-Inclusive terms','Cancellation rules'].map(x=>`<div><span>${x}</span><span class="check-needed">Confirm</span></div>`).join('')}</div>${r.promotion?`<h3 class="detail-heading">Publisher promotion text</h3><p class="section-caption">${esc(r.promotion)}</p><div class="data-state">This is published wording, not confirmation that the package applies to your quote.</div>`:''}<h3 class="detail-heading">Find a matching quote</h3><p class="section-caption">Keep the same sailing and ask for every required cost. The quote button below copies a brief; it sends nothing.</p><div class="source-actions">${sourceLinks(r)}</div><details class="chart-data"><summary>See the quote request before copying</summary><pre class="quote-preview">${esc(makeQuote(r,f?.column))}</pre></details>`;}
function sourceLinks(r){const seen=new Set(),links=[];for(const s of [...(r.retail_prices||[]),...(r.sources||[])]){const u=safeURL(s.url);if(!u||seen.has(u))continue;if(s.scope&&s.scope!=='dated_sailing')continue;seen.add(u);links.push(withLink(u,s.provider||'Seller source'));if(links.length===3)break}links.push(withLink('https://www.cruiseline.co.uk/cruise-lines/windstar-cruises/','The Cruise Line search'));links.push(withLink('https://www.google.com/search?q='+encodeURIComponent('"'+r.cruise_id+'" Windstar quote'),'Search exact cruise ID'));return links.join('');}
function pricesHTML(r){const f=detailRate(),retail=[...(r.retail_prices||[])].sort((a,b)=>String(a.provider).localeCompare(String(b.provider))||(a.fare_pp_pence||Infinity)-(b.fare_pp_pence||Infinity));
 return `<h3 class="detail-heading" style="margin-top:0">Published cabin guides</h3><p class="section-caption">Literal supplier fare columns, not guaranteed available cabin categories. ${info('cabin','Understand supplier cabin columns')}</p><div class="table-scroll"><table class="data-table"><caption class="sr-only">Published raw supplier fare cells for ${esc(r.itinerary)}</caption><thead><tr><th scope="col">Supplier column</th><th scope="col">Published GBP cell</th><th scope="col">Estimated for 2</th><th scope="col">History</th></tr></thead><tbody>${r.fares.map(([c,n])=>`<tr ${c===f?.column?'class="selected-row"':''}><td>${esc(c)}${c===f?.column?'<small>Current guide selection</small>':''}</td><td class="money">${money(n,true)}</td><td class="money">${money(n*2,true)}</td><td><button class="text-link" data-action="detail-tab" data-tab="history" data-column="${esc(c)}">View ${icon('arrow-right','sm')}</button></td></tr>`).join('')}</tbody></table></div><div class="notice">Price units, occupancy, taxes and fees still require confirmation. The multiplication above is a research guide, not the seller's final two-person price.</div><h3 class="detail-heading">Seller evidence for this departure</h3><p class="section-caption">Retained advertisements matched to ship, date and duration. Cabin grades, inclusions and final terms still need matching. ${info('agency','About seller comparisons')}</p>${retail.length?`<div class="table-scroll"><table class="data-table"><caption class="sr-only">Dated, unverified seller advertisements</caption><thead><tr><th scope="col">Seller & observation</th><th scope="col">Advertised category</th><th scope="col">Per person</th><th scope="col">Evidence</th></tr></thead><tbody>${retail.map(v=>{const age=(Date.now()-Date.parse(v.observed_at))/3600000;return `<tr><td>${withLink(v.url,v.provider)}<small>${esc(dateTime(v.observed_at))}${age>48?' · Recheck age':''}</small></td><td>${esc(v.cabin)}<small>${esc(String(v.basis||'advertisement').replaceAll('_',' '))}</small></td><td class="money">${money(v.fare_pp_pence,true)}${Number.isFinite(v.pair_total_pence)?`<small>Explicit pair: ${money(v.pair_total_pence,true)}</small>`:''}</td><td>${v.price_conflict?'<span class="check-needed">Conflicting values</span>':'Unverified advert'}<small>Availability not confirmed</small></td></tr>`}).join('')}</tbody></table></div>`:`<div class="notice">No exact matched seller advertisement is stored for this voyage. Use the seller links or copy a quote request.</div>`}<div class="notice">Shared provider brands are not independent comparisons. Do not multiply a seller's rounded per-person headline when it supplies an explicit two-adult quote.</div>`;
}
function dateOptions(r){return PRODUCTS.filter(p=>p.family_id===r.family_id).sort((a,b)=>a.departure.localeCompare(b.departure))}
function datesHTML(r){const a=dateOptions(r),unique=new Set(a.map(x=>x.departure)).size;return `<div class="chart-title"><div><h3>${unique} dates. One itinerary family.</h3><p>Same ship, itinerary, published duration and product type. ${info('otherdates','About comparing different departure dates')}</p></div></div>${a.length>1?'<div class="chart-wrap"><canvas id="dateChart" role="img" aria-label="Estimated guides for two across actual departure dates"></canvas></div>':'<div class="notice">Only one future date is present for this exact itinerary family in the published snapshot.</div>'}<p class="section-caption">Select a date to open its own prices and evidence. Guides below use each date's lowest published column, which can differ.</p><div class="table-scroll"><table class="data-table"><caption class="sr-only">All retained dates for this itinerary family</caption><thead><tr><th scope="col">Departure</th><th scope="col">Lowest guide for 2</th><th scope="col">Seller evidence</th><th scope="col">Cruise ID</th></tr></thead><tbody>${a.map(v=>`<tr ${v.id===r.id?'class="selected-row"':''}><td><button class="date-table-button" data-action="voyage" data-id="${esc(v.id)}">${esc(day(v.departure))}${v.id===r.id?' · Selected':''}</button></td><td class="money">${money(Number.isFinite(v.low_pence)?v.low_pence*2:NaN,true)}</td><td>${v.retail_advert_count||0} retained records</td><td><small>${esc(v.cruise_id)}</small></td></tr>`).join('')}</tbody></table></div>`;}
function historyHTML(r){const cols=r.fares.map(x=>x[0]);if(!cols.includes(DETAIL_COLUMN))DETAIL_COLUMN=cols[0]||'';const h=r.price_history?.[DETAIL_COLUMN],pts=(h?.points||[]).filter(p=>Number.isFinite(p[1])&&Number.isFinite(Date.parse(p[0]))).sort((a,b)=>Date.parse(a[0])-Date.parse(b[0]));
 return `<div class="price-column-select"><label for="historyColumn">Follow one supplier column</label><select id="historyColumn">${cols.map(c=>`<option ${c===DETAIL_COLUMN?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}</select>${info('drop','Understand recorded price drops')}</div><p class="section-caption">The published GBP cell, not a final quote. ${pts.length} actual observation${pts.length===1?'':'s'}${pts.length?' from '+esc(day(pts[0][0]))+' to '+esc(day(pts.at(-1)[0])):''}.</p>${pts.length>=2?`<div class="history-kpis"><div><span>First recorded cell</span><strong>${money(pts[0][1])}</strong></div><div><span>Lowest observed cell</span><strong>${money(Math.min(...pts.map(x=>x[1])))}</strong></div><div><span>Latest recorded cell</span><strong>${money(pts.at(-1)[1])}</strong></div></div><div class="chart-wrap history-chart"><canvas id="historyChart" role="img" aria-label="Actual observed GBP values for supplier column ${esc(DETAIL_COLUMN)}"></canvas></div><p class="data-state">The stepped line only joins recorded checks; prices between checks are unknown. History starts with ORION's first observation, not the beginning of the supplier's sale.</p>`:`<div class="empty-state">${icon('chart-no-axes-combined')}<h3>${pts.length?'One observation. No trend yet.':'No history for this column yet.'}</h3><p>At least two dated checks are needed to show a price change. ORION will not invent earlier values.</p></div>`}${pts.length?`<details class="chart-data" ${pts.length<2?'open':''}><summary>Read all ${pts.length} chart values</summary><div class="table-scroll"><table class="data-table"><caption class="sr-only">Each actual plotted price observation</caption><thead><tr><th scope="col">Observed at, UK time</th><th scope="col">Published GBP cell</th></tr></thead><tbody>${pts.map(p=>`<tr><td>${esc(dateTime(p[0]))}</td><td class="money">${money(p[1],true)}</td></tr>`).join('')}</tbody></table></div></details>`:''}<div class="notice">A raw drop is not a verified saving against today's other sellers. Confirm the exact cabin, final UK payable total and inventory before booking. ${withLink(DATA.feed.source_url,'Original supplier feed')}</div>`;
}
function renderVoyage(){if(!DETAIL)return;const renderID=++DETAIL_RENDER;destroyDetailChart();const r=DETAIL;const tabs=[['overview','Overview'],['prices','Cabins & sellers'],['dates','All dates'],['history','Price history']];$('voyageContent').innerHTML=`<div class="voyage-head"><div class="voyage-kicker">${icon('ship')}${esc(r.ship)} · ${esc(r.region)}</div><h2 id="voyageTitle" tabindex="-1">${esc(r.itinerary)}</h2><button class="icon-btn close voyage-close" data-close="voyageDialog" aria-label="Close voyage">${icon('x')}</button><div class="voyage-context"><span>${icon('calendar-days')}${esc(day(r.departure))}</span><span>${icon('clock-3')}${r.duration} published days</span><span>${esc(r.from_port)} → ${esc(r.to_port)}</span></div></div><div class="voyage-tabs" role="tablist" aria-label="Voyage detail">${tabs.map(([k,t])=>`<button role="tab" id="tab-${k}" data-action="detail-tab" data-tab="${k}" aria-selected="${DETAIL_TAB===k}" aria-controls="voyagePane" tabindex="${DETAIL_TAB===k?'0':'-1'}">${t}</button>`).join('')}</div><div class="voyage-pane" id="voyagePane" role="tabpanel" aria-labelledby="tab-${DETAIL_TAB}">${DETAIL_TAB==='prices'?pricesHTML(r):DETAIL_TAB==='dates'?datesHTML(r):DETAIL_TAB==='history'?historyHTML(r):overviewHTML(r)}</div><div class="voyage-footer" id="voyageFooter"></div>`;updateVoyageFooter();writeURL();requestAnimationFrame(()=>{if(renderID!==DETAIL_RENDER||!$('voyageDialog').open)return;if(!$('voyageDialog').contains(document.activeElement))$('voyageTitle')?.focus({preventScroll:true});if(DETAIL_TAB==='history')renderHistoryChart();if(DETAIL_TAB==='dates')renderDateChart()});}
function updateVoyageFooter(){if(!DETAIL||!$('voyageFooter'))return;const r=DETAIL;$('voyageFooter').innerHTML=`<div>${saveButton(r,true)}<button class="button quiet" data-action="share-voyage">${icon('share-2')}<span class="label-hide">Share</span></button>${compareControl(r)}</div><button class="button primary" data-action="quote">${icon('copy')}Copy quote request</button>`;}
function changeDetailTab(tab,column){DETAIL_TAB=['overview','prices','dates','history'].includes(tab)?tab:'overview';if(column)DETAIL_COLUMN=column;renderVoyage();requestAnimationFrame(()=>$('tab-'+DETAIL_TAB)?.focus({preventScroll:true}));}
function baseChart(){const c=palette();return {responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false},tooltip:{backgroundColor:c.ink,titleColor:c.bg,bodyColor:c.bg,padding:11,displayColors:false,titleFont:{size:11},bodyFont:{size:11}}},scales:{x:{grid:{display:false},border:{color:c.line},ticks:{color:c.muted,font:{size:10},maxTicksLimit:7}},y:{grid:{color:c.line,drawTicks:false},border:{display:false},ticks:{color:c.muted,font:{size:10},padding:8,callback:v=>fmtGBP.format(v/100)}}}}}
function renderHistoryChart(){const canvas=$('historyChart');if(!canvas)return;window.Chart?.getChart(canvas)?.destroy();if(!window.Chart){canvas.replaceWith(Object.assign(document.createElement('p'),{className:'notice',textContent:'The chart library did not load. The exact observation table below is still available.'}));return}const pts=(DETAIL.price_history?.[DETAIL_COLUMN]?.points||[]).filter(p=>Number.isFinite(p[1])&&Number.isFinite(Date.parse(p[0]))).map(p=>({x:Date.parse(p[0]),y:p[1]})).sort((a,b)=>a.x-b.x);const c=palette(),opt=baseChart();opt.scales.x={...opt.scales.x,type:'linear',ticks:{...opt.scales.x.ticks,callback:v=>shortDay(v)}};opt.scales.y.title={display:true,text:'Published GBP cell',color:c.muted,font:{size:10}};opt.plugins.tooltip.callbacks={title:items=>dateTime(items[0].raw.x),label:ctx=>DETAIL_COLUMN+': '+money(ctx.raw.y,true)};detailChart=new Chart(canvas,{type:'line',data:{datasets:[{data:pts,borderColor:c.blue,backgroundColor:c.blue,borderWidth:2,stepped:'before',pointRadius:4,pointHoverRadius:6,fill:false}]},options:opt});}
function renderDateChart(){const canvas=$('dateChart');if(!canvas||!window.Chart)return;Chart.getChart(canvas)?.destroy();const options=dateOptions(DETAIL).filter(r=>Number.isFinite(r.low_pence)),points=options.map(r=>({x:Date.parse(r.departure+'T12:00:00Z'),y:r.low_pence*2,id:r.id}));const c=palette(),opt=baseChart();opt.scales.x={...opt.scales.x,type:'linear',ticks:{...opt.scales.x.ticks,callback:v=>new Date(v).toLocaleDateString('en-GB',{month:'short',year:'2-digit',timeZone:'UTC'})}};opt.scales.y.title={display:true,text:'Lowest guide for two',color:c.muted,font:{size:10}};opt.plugins.tooltip.callbacks={title:items=>day(items[0].raw.x),label:ctx=>money(ctx.raw.y,true)+' estimated for two',afterLabel:()=> 'Select to open this departure'};opt.onClick=(e,els)=>{if(els.length)openVoyage(points[els[0].index].id)};detailChart=new Chart(canvas,{type:'scatter',data:{datasets:[{data:points,pointRadius:4,pointHoverRadius:7,backgroundColor:c.blue}]},options:opt});}
function renderCalendar(a=filtered()){if(!CALENDAR_OPEN)return;if(calendarChart){calendarChart.destroy();calendarChart=null}const year=$('calendarYear').value,months=Array.from({length:12},(_,i)=>{const key=year+'-'+String(i+1).padStart(2,'0'),group=a.filter(r=>r.departure.startsWith(key)&&Number.isFinite(fare(r)?.amount));return {key,label:new Date(Number(year),i,1).toLocaleDateString('en-GB',{month:'short'}),min:group.length?Math.min(...group.map(r=>fare(r).amount*2)):null,count:group.length}});
 $('calendarTable').innerHTML=`<div class="table-scroll"><table class="data-table"><caption class="sr-only">Lowest matching guide by month for ${esc(year)}</caption><thead><tr><th>Month</th><th>Matching departures</th><th>Lowest guide for two</th></tr></thead><tbody>${months.map(m=>`<tr><td>${m.count?`<button class="date-table-button" data-month="${m.key}">${m.label} ${year}</button>`:m.label+' '+year}</td><td>${m.count}</td><td class="money">${m.min!==null?money(m.min):'No matching departures'}</td></tr>`).join('')}</tbody></table></div>`;
 const good=months.some(m=>m.count);$('calendarChart').hidden=!good;$('calendarFallback').innerHTML=good?'':'<div class="notice">No matching departures in this year. Choose another calendar year or broaden your date filters.</div>';if(!good)return;if(!window.Chart){$('calendarFallback').innerHTML='<p class="notice">The chart could not load. All monthly values are available in the data table.</p>';$('calendarChart').hidden=true;return}const c=palette(),opt=baseChart();opt.scales.y.beginAtZero=true;opt.plugins.tooltip.callbacks={title:items=>months[items[0].dataIndex].label+' '+year,label:ctx=>money(ctx.raw)+' estimated for two',afterLabel:ctx=>months[ctx.dataIndex].count+' matching products · Select month'};opt.onClick=(e,els)=>{if(els.length&&months[els[0].index].count)chooseMonth(months[els[0].index].key)};calendarChart=new Chart($('calendarChart'),{type:'bar',data:{labels:months.map(m=>m.label),datasets:[{data:months.map(m=>m.min),backgroundColor:c.blue,borderRadius:4,maxBarThickness:36}]},options:opt});}
function chooseMonth(month){const [y,m]=month.split('-').map(Number);state.from=month+'-01';state.to=strTime(Date.UTC(y,m,0));state.page=1;render();toast('Showing departures in '+new Date(y,m-1,1).toLocaleDateString('en-GB',{month:'long',year:'numeric'}));}
function openComparison(){const rows=[...compared].map(id=>BY_ID.get(id)).filter(Boolean);if(!rows.length){toast('Choose up to three voyages to compare.');return}const cells=[['Departure',r=>day(r.departure)],['Published duration',r=>r.duration+' days'],['Route',r=>r.from_port+' → '+r.to_port],['Type',r=>r.kind],['Lowest cruise guide for 2',r=>money(Number.isFinite(r.low_pence)?r.low_pence*2:NaN,true)],['Recorded change',r=>r.drop?.pct>0?'Up to '+pct(r.drop.pct)+' in '+r.drop.column:'No recorded decrease'],['Seller evidence',r=>r.retail_advert_count+' retained advertisements'],['Available cabin confirmed?',()=> 'No'],['Final UK costs confirmed?',()=> 'No']];$('comparisonContent').innerHTML=`<div class="table-scroll"><table class="data-table comparison-table"><caption class="sr-only">Comparing selected voyages, not claiming like-for-like savings</caption><thead><tr><th scope="col">What matters</th>${rows.map(r=>`<th scope="col"><div class="compare-title">${esc(r.itinerary)}</div><small>${esc(r.ship)}</small></th>`).join('')}</tr></thead><tbody>${cells.map(([label,fn])=>`<tr><th scope="row">${label}</th>${rows.map(r=>`<td class="${label.startsWith('Lowest')?'table-amount':''}">${esc(fn(r))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Next step</th>${rows.map(r=>`<td><button class="text-link" data-action="compare-open-voyage" data-id="${esc(r.id)}">Inspect evidence ${icon('arrow-right','sm')}</button></td>`).join('')}</tr></tbody></table></div><div class="notice">Different departures, cabins and packages are different purchases. This comparison helps build a shortlist; it does not prove a market saving. Flights and unconfirmed mandatory costs are not added to these guides.</div>`;modalOpen('comparisonDialog');}
function renderOffers(){if(!DATA)return;const show=$('showExcluded').checked,all=DATA.offers||[],rows=all.filter(x=>show||x.decision!=='excluded');$('offerGrid').innerHTML=rows.map(x=>{const label={needs_verification:'Needs verification',excluded:'Excluded for now',eligible_unpriced:'Eligible route · no quote',already_captured:'Already included',priced_candidate:'Quoted candidate · recheck'}[x.decision]||'Needs verification';return `<article class="offer-card"><div class="offer-top"><span>${esc(String(x.method||'public offer').replaceAll('_',' '))}</span><span>${esc(x.campaign_state||'unknown')}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p><span class="offer-state">${label}</span><div class="offer-dimensions"><div><span>Evidence</span><strong>${esc(String(x.evidence_level||'unknown').replaceAll('_',' '))}</strong></div><div><span>Eligibility</span><strong>${esc(x.eligibility||'unknown')}</strong></div><div><span>Stage reached</span><strong>${esc(String(x.transaction_stage||'not tested').replaceAll('_',' '))}</strong></div></div><p class="offer-next"><strong>Next check:</strong> ${esc(x.next_action)}</p><div class="source-actions">${(x.sources||[]).map(s=>withLink(s.url,'Read source terms')).join('')}</div><div class="offer-bottom"><span>Observed ${esc(day(x.checked_on))}</span><span>No discount applied</span></div></article>`}).join('')||'<div class="empty-state"><h3>No offer routes in this edition.</h3><p>This does not establish that no offers exist.</p></div>';}
function openStatus(){if(!DATA){$('statusTitle').textContent='Catalogue unavailable';$('statusContent').innerHTML='<p class="notice">The published data could not be read. It has not been labelled as a successful price check.</p><button class="button secondary" data-action="reload">Reload published edition</button>';modalOpen('statusDialog');return}const age=snapshotAge();$('statusTitle').textContent='What has actually been checked?';$('statusContent').innerHTML=`<dl class="status-rows"><div><dt>Supplier fare snapshot</dt><dd>${esc(dateTime(DATA.feed.observed_at))}<small>${Number.isFinite(age)?Math.floor(age)+' hours old':'Age unknown'}. Each seller advert has its own timestamp.</small></dd></div><div><dt>Last collector success</dt><dd>${esc(dateTime(DATA.collector_last_success))}<small>May relate to another source, not this price feed.</small></dd></div><div><dt>Website edition prepared</dt><dd>${esc(dateTime(DATA.built_at))}<small>Edition ${esc(DATA.release)}. The last published snapshot stays available.</small></dd></div><div><dt>Automatic website publication</dt><dd>Not enabled<small>A scheduled research task does not automatically update this page.</small></dd></div><div><dt>Coverage in this edition</dt><dd>${fmtNum.format(PRODUCTS.length)} future published products<small>${DATA.statistics.ship_departure_pairs||'Multiple'} ship / departure pairs. Products also include combined cruises and tours.</small></dd></div><div><dt>Verified exceptional bargains</dt><dd>0<small>No fresh, independently matched, UK-bookable discount has passed all checks.</small></dd></div></dl><div class="notice">Reloading retrieves the latest published website. It does not launch research, contact suppliers or confirm live cabin inventory.</div><div class="status-actions"><button class="button secondary" data-action="reload">${icon('refresh-cw')}Reload snapshot</button><button class="button quiet" data-action="help" data-topic="freshness">How updates work ${icon('arrow-right','sm')}</button></div>`;modalOpen('statusDialog');}
function exportSaved(){const rows=[...saved].map(id=>BY_ID.get(id)).filter(Boolean);if(!rows.length){toast('Save a voyage before exporting.');return}const csvField=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const fields=['Ship','Itinerary','Departure','Published days','Supplier cruise ID','Lowest guide for two GBP','Guide status','Feed observed UTC','Voyage link'];const lines=[fields,...rows.map(r=>[r.ship,r.itinerary,r.departure,r.duration,r.cruise_id,Number.isFinite(r.low_pence)?(r.low_pence*2/100).toFixed(2):'','UNVERIFIED estimate; final costs and inventory unknown',DATA.feed.observed_at,new URL('?voyage='+encodeURIComponent(r.id),base).href])];const blob=new Blob(['\uFEFF'+lines.map(a=>a.map(csvField).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download='ORION-shortlist-'+today+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Shortlist exported with source dates and price caveats.');}

let searchTimer;
$('query')?.addEventListener('input',e=>{clearTimeout(searchTimer);state.q=e.target.value;state.page=1;searchTimer=setTimeout(()=>render(),130)});
$('region')?.addEventListener('change',e=>{state.region=e.target.value;state.page=1;render()});
$('sort')?.addEventListener('change',e=>{state.sort=e.target.value;state.page=1;render()});
$('calendarYear')?.addEventListener('change',()=>renderCalendar());
$('showExcluded')?.addEventListener('change',renderOffers);
$('filterForm')?.addEventListener('submit',e=>{e.preventDefault();const from=$('filterFrom').value,to=$('filterTo').value;$('filterTo').setCustomValidity(from&&to&&from>to?'The end date must be on or after the start date.':'');if(!$('filterForm').reportValidity())return;for(const k of ['from','to','ship','duration','budget','kind','cabin']){const f=$('filter'+k[0].toUpperCase()+k.slice(1));state[k]=f.value}state.page=1;modalClose('filterDialog');render();});
$('filterTo')?.addEventListener('input',()=>$('filterTo').setCustomValidity(''));
$('filterFrom')?.addEventListener('input',()=>$('filterTo').setCustomValidity(''));
$('voyageDialog')?.addEventListener('change',e=>{if(e.target.id==='historyColumn'){DETAIL_COLUMN=e.target.value;renderVoyage();requestAnimationFrame(()=>$('historyColumn')?.focus({preventScroll:true}));}});
document.addEventListener('keydown',e=>{
 if(e.key==='Tab'){
  const d=MODAL_STACK.filter(x=>x.open).at(-1);
  if(d){const items=[...d.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary,[tabindex]')].filter(x=>x.tabIndex>=0&&x.getClientRects().length&&getComputedStyle(x).visibility!=='hidden');const first=items[0],last=items.at(-1);if(first&&((!e.shiftKey&&document.activeElement===last)||(e.shiftKey&&document.activeElement===first)||!d.contains(document.activeElement))){e.preventDefault();(e.shiftKey?last:first).focus();return}}
 }
 const isEditing=e.target.matches('input,textarea,select,[contenteditable=true]');
 if(e.key==='/'&&!isEditing&&!document.querySelector('dialog[open]')){e.preventDefault();$('query').focus();}
 if(e.key==='?'&&!isEditing){e.preventDefault();openHelp('start')}
 const t=e.target.closest('[role=tab]');if(t&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const a=['overview','prices','dates','history'];let i=a.indexOf(DETAIL_TAB);i=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;changeDetailTab(a[i]);}
});
document.addEventListener('click',async e=>{
 const view=e.target.closest('[data-view]');if(view){if(DATA)nav(view.dataset.view);return}
 const quick=e.target.closest('[data-quick]');if(quick){state.evidence=quick.dataset.quick;state.page=1;render();return}
 const mode=e.target.closest('[data-layout]');if(mode){layout=mode.dataset.layout;store.write('layout',layout);render();return}
 const page=e.target.closest('[data-page]');if(page&&!page.disabled){state.page=Number(page.dataset.page);render({scroll:true});return}
 const chip=e.target.closest('[data-remove-filter]');if(chip){state[chip.dataset.removeFilter]='';state.page=1;render();return}
 const preset=e.target.closest('[data-preset]');if(preset){if(preset.dataset.preset==='90'){$('filterFrom').value=today;$('filterTo').value=strTime(Date.parse(today+'T12:00:00Z')+90*86400000)}else{$('filterFrom').value=preset.dataset.preset+'-01-01';$('filterTo').value=preset.dataset.preset+'-12-31'}$('filterTo').setCustomValidity('');return}
 const month=e.target.closest('[data-month]');if(month){chooseMonth(month.dataset.month);return}
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
 if(action==='help'){openHelp(b.dataset.topic||'start');return}
 if(action==='tip'){openTip(b.dataset.tip,b);return}
 if(action==='theme'){theme=theme==='system'?'light':theme==='light'?'dark':'system';store.write('appearance',theme);applyTheme();toast('Appearance: '+theme);if(CALENDAR_OPEN)renderCalendar();if(DETAIL_TAB==='history'&&$('voyageDialog').open){destroyDetailChart();renderHistoryChart()}if(DETAIL_TAB==='dates'&&$('voyageDialog').open){destroyDetailChart();renderDateChart()}return}
 if(action==='status'){openStatus();return}
 if(action==='reload'){location.reload();return}
 if(action==='retry-data'){loadCatalogue();return}
 if(!DATA)return;
 if(action==='filters'){showFilters(b.dataset.focus);return}
 if(action==='reset-filter-form'){for(const k of ['From','To','Ship','Duration','Budget','Kind','Cabin'])$('filter'+k).value='';$('filterTo').setCustomValidity('');return}
 if(action==='reset'){resetFilters();return}
 if(action==='agency-view'){state.view='all';state.evidence='agency';state.page=1;render();return}
 if(action==='unverify'){state.evidence='all';state.page=1;render();return}
 if(action==='calendar'){CALENDAR_OPEN=!CALENDAR_OPEN;$('calendarPanel').hidden=!CALENDAR_OPEN;$('calendarToggle').setAttribute('aria-expanded',String(CALENDAR_OPEN));if(CALENDAR_OPEN)renderCalendar();else if(calendarChart){calendarChart.destroy();calendarChart=null}return}
 if(action==='save'){toggleSaved(b.dataset.id);return}
 if(action==='select-compare'){toggleCompare(b.dataset.id);return}
 if(action==='compare'){openComparison();return}
 if(action==='clear-compare'){compared.clear();store.write('compare',[]);render();return}
 if(action==='voyage'){openVoyage(b.dataset.id,b.dataset.tab,b.dataset.column);return}
 if(action==='compare-open-voyage'){modalClose('comparisonDialog');openVoyage(b.dataset.id);return}
 if(action==='detail-tab'){changeDetailTab(b.dataset.tab,b.dataset.column);return}
 if(action==='retry-detail'){openVoyage(DETAIL_ID,DETAIL_TAB,DETAIL_COLUMN);return}
 if(action==='quote'&&DETAIL){await copyText(makeQuote(DETAIL,DETAIL_TAB==='history'?DETAIL_COLUMN:detailRate()?.column),'Quote request copied. Nothing has been sent.');return}
 if(action==='share-voyage'&&DETAIL_ID){const url=new URL(base);url.searchParams.set('voyage',DETAIL_ID);await copyText(url.href,'Direct voyage link copied.');return}
 if(action==='share-search'){const url=new URL(location.href);url.searchParams.delete('voyage');url.searchParams.delete('tab');if(state.view==='saved')url.searchParams.set('view','all');await copyText(url.href,state.view==='saved'?'Search link copied. Your saved list is not shared.':'Search and filters copied as a shareable link.');return}
 if(action==='export'){exportSaved();return}
});
// Pointer hover and keyboard focus use the same short explanations as a tap.
let hoverTimer;
document.addEventListener('pointerover',e=>{const t=e.target.closest('.info-btn[data-tip]');if(t&&e.pointerType==='mouse'){clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>openTip(t.dataset.tip,t),450)}});
document.addEventListener('focusin',e=>{const t=e.target.closest('.info-btn[data-tip]');if(t&&t.matches(':focus-visible'))openTip(t.dataset.tip,t)});
document.addEventListener('pointerout',e=>{if(e.target.closest('.info-btn[data-tip]'))clearTimeout(hoverTimer)});
window.addEventListener('popstate',()=>{if(!DATA)return;const p=readURL();render();if(p.get('voyage'))openVoyage(p.get('voyage'),p.get('tab'));else modalClose('voyageDialog')});
function validateData(d){if(d?.schema_version!==2||!Array.isArray(d.products)||!d.feed)throw Error('Unexpected catalogue format');if(d.products.length<100)throw Error('The published catalogue is unexpectedly small');}
async function loadCatalogue(){const source=document.querySelector('meta[name=orion-catalogue]')?.content;if(!source)return;$('results').innerHTML='<div class="loading-state" role="status"><span class="spinner"></span><h3>Opening the published catalogue</h3><p>Your saved choices stay in this browser.</p></div>';
 try{DATA=await fetchJSON(source);validateData(DATA);PRODUCTS=DATA.products.filter(p=>p.departure>=today&&Array.isArray(p.fares));BY_ID=new Map(PRODUCTS.map(p=>[p.id,p]));for(const r of PRODUCTS)r._search=norm([r.ship,r.itinerary,r.region,r.from_port,r.to_port,r.cruise_id,r.voyage_id].join(' '));
 saved=new Set([...saved].filter(id=>BY_ID.has(id)));compared=new Set([...compared].filter(id=>BY_ID.has(id)));store.write('saved',[...saved]);store.write('compare',[...compared]);
 populateSelect('region',PRODUCTS.map(p=>p.region),'Everywhere');populateSelect('filterShip',PRODUCTS.map(p=>p.ship),'Any ship');populateSelect('filterCabin',PRODUCTS.flatMap(p=>p.fares.map(f=>f[0])),'Lowest published guide');
 const years=[...new Set(PRODUCTS.map(p=>p.departure.slice(0,4)))].sort();$('calendarYear').innerHTML=years.map(y=>`<option value="${y}">${y}</option>`).join('');$('calendarYear').value=years.find(y=>y>=today.slice(0,4))||years[0];
 const params=readURL();for(const [field,sel] of [['region','region'],['ship','filterShip'],['cabin','filterCabin']])if(state[field]&&![...$(sel).options].some(x=>x.value===state[field]))state[field]='';
 $('productCount').textContent=fmtNum.format(PRODUCTS.length);$('dropCount').textContent=fmtNum.format(PRODUCTS.filter(r=>r.drop?.pct>0).length);$('agencyCount').textContent=fmtNum.format(PRODUCTS.filter(r=>r.retail_advert_count>0).length);$('snapshotLabel').textContent='Supplier snapshot · '+day(DATA.feed.observed_at);$('buildLabel').textContent='Edition '+DATA.release;
 const old=snapshotAge()>48;$('staleBanner').hidden=!old;if(old)$('staleBanner').innerHTML=`${icon('clock-3')}<span>The supplier snapshot is ${Number.isFinite(snapshotAge())?Math.floor(snapshotAge()/24)+' days old':'undated'}. Recheck prices before acting.</span><button class="inline-link" data-action="status">See update status</button>`;
 render();if(params.get('voyage'))openVoyage(params.get('voyage'),params.get('tab'));if(params.get('help'))openHelp(params.get('help'));initialLoad=false;
 }catch(e){DATA=null;$('resultCount').textContent='Catalogue could not load';$('snapshotLabel').textContent='Published data unavailable';$('results').innerHTML=`<div class="empty-state">${icon('cloud-off')}<h3>The catalogue couldn't be opened.</h3><p>Your saved choices have not been cleared. Try loading the published edition again. This error is not a “no cruises found” result.</p><button class="button secondary" data-action="retry-data">Try again ${icon('refresh-cw')}</button> <a class="button quiet" href="help.html">Read the guide</a></div>`;console.warn('ORION catalogue:',e.message)}
}
loadCatalogue();
})();
